/**
 * SLATE — credit cards, bank by bank.
 *
 * Each bank's own standard personal credit card, as it sells it: its name,
 * whether a balance can be carried (`revolving`) or the whole statement is
 * taken from the current account each month (`charge`, the deferred-debit
 * card much of continental Europe carries), its rate or the range it prices
 * an applicant within, its yearly fee, its minimum payment and late fee, and
 * the days between the statement and the payment due. And each country's law
 * on cards, where it has one: a cap on the rate, a cap on a late fee.
 *
 * Generated by `probe/gen-cards.cjs` from research that read each bank's own
 * terms (`probe/cards/`), where they were found. A bank with no card on
 * record gets SLATE's estimate (`systems/credit.ts`), and the screen says so.
 * Amounts are in the bank's currency's hundredths.
 */

import type { Money } from '../core/money';

export interface CardProduct {
  name: string;
  kind: 'revolving' | 'charge';
  /** The standard purchase rate a year. */
  apr?: number;
  /** Or the range the bank prices an applicant within, the best record at the bottom. */
  aprFrom?: number;
  aprTo?: number;
  annualFee?: Money;
  /** The least a statement asks: a share of it, plus the month's interest where the bank adds it, never under a floor. */
  minimumShare?: number;
  minimumPlusInterest?: boolean;
  minimumFloor?: Money;
  lateFee?: Money;
  /** Days from the statement to the payment due. */
  graceDays?: number;
  /** What a bounced payment costs. */
  returnedPaymentFee?: Money;
  /** The US penalty rate, after a payment 60 days late. */
  penaltyApr?: number;
  /** A cash advance: its fee (a share, never under a minimum), its rate, and its limit (a share of the credit limit, or an amount). */
  cashFeeShare?: number;
  cashFeeMin?: Money;
  cashApr?: number;
  cashLimitShare?: number;
  cashLimit?: Money;
  /** An introductory purchase rate, for so many months from opening. */
  introApr?: number;
  introMonths?: number;
  /** A balance transfer: its fee (a share, never under a minimum), its rate after any introductory rate, and that rate and its months. */
  transfer?: { feeShare?: number; feeMin?: Money; apr?: number; introApr?: number; introMonths?: number };
  /** A money transfer into the holder's own account, where the card offers one: its fee as a share. */
  moneyTransferFee?: number;
  /** A plan that pays a purchase off in equal months: its monthly fee as a share, the most the bank says it charges, and the bank's words. */
  planFeeShare?: number;
  planWords?: string;
  /** Cash back or points on every purchase at the card's base rate, and the bank's words for its rewards. */
  rewardsRate?: number;
  rewardsWords?: string;
  /** The currency its amounts are in, where it isn't the bank's: a dollar card in a dollarized economy. */
  currency?: string;
  source: string;
  asOf: string;
}

export interface CardLaw {
  /** The highest rate a card may charge a year. */
  aprCap?: number;
  /** The most a late fee may be, in the country's currency's hundredths. */
  lateFeeCap?: Money;
  law: string;
  source: string;
}

